{"research_date": "2026-09-10", "pairs": [{"pair_id": "conflict_5a94ec14e3e97a3a2addb511", "claim_ids": ["claim_5e2fa1ade9f4703c3627a6c4", "claim_ffd6a1250c24704c9800f5e2"], "query_ids": ["q_352"], "claims": [{"claim_id": "claim_5e2fa1ade9f4703c3627a6c4", "quote": "Thus, the value of the steel/aluminum content is the total price paid or payable for that content, which is the total payment (direct or indirect, and exclusive of any costs, charges, or expenses incurred for transportation, insurance, and related services incident to the international shipment of the merchandise from the country", "url": "https://diaztradelaw.com/section-232-valuation-in-a-gray-area-what-importers-need-to-know", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {}}, {"claim_id": "claim_ffd6a1250c24704c9800f5e2", "quote": "The value of the steel/aluminum content should be determined in accordance with the principles of the Customs Valuation Agreement, as implemented in 19 U.S.C. 1401a.", "url": "https://diaztradelaw.com/section-232-valuation-in-a-gray-area-what-importers-need-to-know", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"legal_authority": "19 U.S.C. 1401a"}}]}, {"pair_id": "conflict_86ea20b077e2d1036492c786", "claim_ids": ["claim_092b925a21d34534e71515d3", "claim_64ab9cf2398dfa4ef752372f"], "query_ids": ["q_353"], "claims": [{"claim_id": "claim_092b925a21d34534e71515d3", "quote": "All General Approved Exclusions (GAEs) and country-level ‘alternative arrangements’ to the Section 232 Steel and Aluminum Duties (including exemptions, absolute quotas, and tariff-rate quotas) were revoked effective 12:01 AM Eastern Time on March 12, 2025.", "url": "https://www.bis.gov/about-bis/bis-leadership-and-offices/SIES/section-232-investigations/section-232-steel-aluminum", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 232 Steel and Aluminum Duties", "announcement_date": "March 12, 2025", "effective_date": "March 12, 2025"}}, {"claim_id": "claim_64ab9cf2398dfa4ef752372f", "quote": "Proclamations 10895 and 10896 of February 2025, among other actions, applied the Section 232 Steel and Aluminum Tariffs to additional steel and aluminum downstream (or “derivative”) products", "url": "https://www.bis.gov/about-bis/bis-leadership-and-offices/SIES/section-232-investigations/section-232-steel-aluminum", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 232 Steel and Aluminum Tariffs", "announcement_date": "February 2025", "effective_date": "February 2025"}}]}, {"pair_id": "conflict_37f885942483180b6dce9701", "claim_ids": ["claim_66a3aec4db97765416280987", "claim_9b7d09ce15f5fa70f92b8e30"], "query_ids": ["q_353"], "claims": [{"claim_id": "claim_66a3aec4db97765416280987", "quote": "June 1, 2026 Presidential Proclamation The proclamation makes the following modifications to the April 2026 framework. - lowering from 25 percent to 15 percent the tariff rate on certain agricultural equipment (e.g., combines and harvesters) and certain heating, ventilation, and air conditioning systems and components that are predominantly for residential use", "url": "https://www.strtrade.com/trade-news-resources/tariff-actions-resources/section-232-tariffs-on-steel-aluminum", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"announcement_date": "June 1, 2026"}}, {"claim_id": "claim_9b7d09ce15f5fa70f92b8e30", "quote": "April 2, 2026 Presidential Proclamation Effective April 6, 2026, tariffs on steel and aluminum and their derivative products were modified as below. However, these changes are superceded by the above June 1, 2026 proclamation. - A flat 50 percent tariff will be imposed on the full value of articles made entirely or almost entirely of aluminum or steel.", "url": "https://www.strtrade.com/trade-news-resources/tariff-actions-resources/section-232-tariffs-on-steel-aluminum", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"announcement_date": "April 2, 2026", "effective_date": "April 6, 2026"}}]}, {"pair_id": "conflict_37c19bfee0dd5a81f39aec0b", "claim_ids": ["claim_0c8872258becbcef71c6b8ba", "claim_dfb0bb92d38f9822ca2b9aff"], "query_ids": ["q_354"], "claims": [{"claim_id": "claim_0c8872258becbcef71c6b8ba", "quote": "Pursuant to Presidential Proclamations 10895 and 10896 of February 10, 2025, Commerce is no longer processing Section 232 Exclusion Requests effective 11:59 PM ET on February 10, 2025, and is no longer accepting or issuing exclusions from the Section 232 Steel and Aluminum Tariffs.", "url": "https://www.bis.gov/about-bis/bis-leadership-and-offices/SIES/section-232-investigations/section-232-steel-aluminum", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 232 Steel and Aluminum Tariffs", "legal_authority": "Presidential Proclamations 10895 and 10896 of February 10, 2025", "reported_policy_status": "no longer processing Section 232 Exclusion Requests"}}, {"claim_id": "claim_dfb0bb92d38f9822ca2b9aff", "quote": "In February, President Trump announced his intent to terminate the Section 232 exclusion process, which has since been allowed to expire.", "url": "https://www.clarkhill.com/news-events/news/update-on-inclusion-requests-pertaining-to-section-232-tariffs-on-steel-and-aluminum", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 232", "reported_policy_status": "allowed to expire"}}]}, {"pair_id": "conflict_852eb41983f9317b211a2182", "claim_ids": ["claim_1eaef644198e425fd52f8972", "claim_a46426e497f2cad935da5a7e"], "query_ids": ["q_355"], "claims": [{"claim_id": "claim_1eaef644198e425fd52f8972", "quote": "25% tariff on full value of steel and aluminum articles and derivatives from the United Kingdom (UK) composed of at least 95% UK-sourced steel/aluminum", "url": "https://www.congress.gov/crs-product/IN12519", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "25%"}}, {"claim_id": "claim_a46426e497f2cad935da5a7e", "quote": "15% tariff on full value of steel and aluminum derivatives from the UK composed of at least 95% UK-sourced steel/aluminum", "url": "https://www.congress.gov/crs-product/IN12519", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "15%"}}]}, {"pair_id": "conflict_dcd9a6a7765a5f0a0e1874cd", "claim_ids": ["claim_2060000b0129f19f143e6c9a", "claim_5040c68179321b76087aa9bf"], "query_ids": ["q_355"], "claims": [{"claim_id": "claim_2060000b0129f19f143e6c9a", "quote": "June 1, 2026 Presidential Proclamation The proclamation makes the following modifications to the April 2026 framework. - lowering from 25 percent to 15 percent the tariff rate on certain agricultural equipment (e.g., combines and harvesters) and certain heating, ventilation, and air conditioning systems and components that are predominantly for residential use", "url": "https://www.strtrade.com/trade-news-resources/tariff-actions-resources/section-232-tariffs-on-steel-aluminum", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"announcement_date": "June 1, 2026"}}, {"claim_id": "claim_5040c68179321b76087aa9bf", "quote": "April 2, 2026 Presidential Proclamation Effective April 6, 2026, tariffs on steel and aluminum and their derivative products were modified as below. However, these changes are superceded by the above June 1, 2026 proclamation. - A flat 50 percent tariff will be imposed on the full value of articles made entirely or almost entirely of aluminum or steel.", "url": "https://www.strtrade.com/trade-news-resources/tariff-actions-resources/section-232-tariffs-on-steel-aluminum", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"announcement_date": "April 2, 2026", "effective_date": "April 6, 2026"}}]}, {"pair_id": "conflict_85113cb10191a2a0f09afb4d", "claim_ids": ["claim_5c0fc6ca04a06b1918b27359", "claim_c2c8a9352778af156a767f2b"], "query_ids": ["q_355"], "claims": [{"claim_id": "claim_5c0fc6ca04a06b1918b27359", "quote": "The previous system in which the tariffs on derivative products were calculated by splitting the customs value between steel, aluminum, copper, and non-metal content has been eliminated.", "url": "https://www.whitecase.com/insight-alert/united-states-modifies-steel-aluminum-and-copper-section-232-tariffs", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {}}, {"claim_id": "claim_c2c8a9352778af156a767f2b", "quote": "All tariffs imposed on products under the steel, aluminum, and copper Section 232 actions will now apply to the full customs value of the imported product, including derivative products.", "url": "https://www.whitecase.com/insight-alert/united-states-modifies-steel-aluminum-and-copper-section-232-tariffs", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"affected_product": "steel, aluminum, and copper Section 232 actions"}}]}, {"pair_id": "conflict_33b60b5f8b0ee584ab524484", "claim_ids": ["claim_9f16382bca1eb1e0689ef9af", "claim_ac67f9f725bf296d1481537f"], "query_ids": ["q_355"], "claims": [{"claim_id": "claim_9f16382bca1eb1e0689ef9af", "quote": "reduced tariffs for certain steel derivatives until December 31, 2027", "url": "https://www.congress.gov/crs-product/IN12519", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"expiration_date": "December 31, 2027"}}, {"claim_id": "claim_ac67f9f725bf296d1481537f", "quote": "The proclamation completely removes certain steel and aluminum derivative products from the scope of the Section 232 actions.", "url": "https://www.whitecase.com/insight-alert/united-states-modifies-steel-aluminum-and-copper-section-232-tariffs", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"affected_product": "certain steel and aluminum derivative products"}}]}, {"pair_id": "conflict_1998d4d0ff47c88d7131ec2a", "claim_ids": ["claim_1f328e8bc1826f396f53a5bc", "claim_f88f4f3eb2be9b0689b15f08"], "query_ids": ["q_355"], "claims": [{"claim_id": "claim_1f328e8bc1826f396f53a5bc", "quote": "10% tariff on full value of derivatives composed of at least 85% U.S.-sourced steel, aluminum, and copper", "url": "https://www.congress.gov/crs-product/IN12519", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "10%"}}, {"claim_id": "claim_f88f4f3eb2be9b0689b15f08", "quote": "Unless otherwise excepted, these products will become subject to the global 10% Section 122 tariff, which is currently in effect until July 24, 2026.", "url": "https://www.whitecase.com/insight-alert/united-states-modifies-steel-aluminum-and-copper-section-232-tariffs", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 122 tariff", "duty_rate": "10%", "effective_date": "currently in effect", "expiration_date": "July 24, 2026"}}]}, {"pair_id": "conflict_62f7d35ad765df4c1b8891b6", "claim_ids": ["claim_5ed6f85841b1081777eeba04", "claim_6425daa5ed697db955cad468"], "query_ids": ["q_356"], "claims": [{"claim_id": "claim_5ed6f85841b1081777eeba04", "quote": "Importers must continue to report countries of melt and pour for all subject steel and steel derivative products, and countries of smelt and cast for all subject aluminum and aluminum derivative products (see CSMS messages 64348411, 64348288, and 65340246).", "url": "https://www.ghy.com/trade-compliance/us-adjusts-section-232-tariffs-on-aluminum-steel-and-copper-full-customs-value-now-applies", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"country_of_origin": "countries of melt and pour for all subject steel and steel derivative products, and countries of smelt and cast for all subject aluminum and aluminum derivative products", "reported_policy_status": "continue to report"}}, {"claim_id": "claim_6425daa5ed697db955cad468", "quote": "Continue to report the countries of melt and pour for all subject steel and steel derivative products and the countries of smelt and cast for all subject aluminum and aluminum derivative products.", "url": "https://content.govdelivery.com/accounts/USDHSCBP/bulletins/4117593", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {}}]}]}

